public void setGroups(List<String> groups) throws SharedGroupException {
  if (groups == null) {
    this.groups = new LinkedList<String>();
  } else {
    try {
      for (Group group : getSharedGroups()) {
        String groupName = group.getProperties().get("sharedRoster.displayName");
        if (!groups.contains(groupName)) {
          throw new SharedGroupException("Cannot remove item from shared group");
        }
      }
      Collection<Group> existingGroups = GroupManager.getInstance().getGroups();
      for (Iterator<String> it = groups.iterator(); it.hasNext(); ) {
        String groupName = it.next();
        try {
          Group group = GroupManager.getInstance().getGroup(groupName);
          String displayName = group.getProperties().get("sharedRoster.displayName");
          if (displayName != null && displayName.equals(groupName)) {
            it.remove();
          }
        } catch (GroupNotFoundException e) {
          for (Group group : existingGroups) {
            String displayName = group.getProperties().get("sharedRoster.displayName");
            if (displayName != null && displayName.equals(groupName)) {
              it.remove();
            }
          }
        }
      }
      this.groups = groups;
    } catch (UnsupportedOperationException | NoSuchElementException | ClassCastException | NullPointerException | LinkageError | ExceptionInInitializerError | SecurityException | IllegalArgumentException e) {
      // Handle the exception, e.g., log the error and take appropriate action
      e.printStackTrace();
    }
  }
}
